  "authActivation.intro": "Authenticatie is uitgeschakeld: elk apparaat op het netwerk kan Tune bedienen, en sommige acties (herstarten, stoppen, een extensie installeren) worden alleen geaccepteerd vanaf de computer waarop Tune draait. Schakel haar in door het wachtwoord van het beheerdersaccount te kiezen.",
  "authActivation.adminAccount": "Beheerdersaccount: {user}",
