  "authActivation.codeWhere": "De code staat in het serverlogboek, op een regel gemarkeerd met TUNE-ACTIVATION-CODE: `journalctl -u <dienst> | grep TUNE-ACTIVATION-CODE` (Linux-dienst), of in de console als Tune met de hand is gestart. Met Docker: `docker logs <container> | grep TUNE-ACTIVATION-CODE`. Op Windows: in het bestand tune-server.log. Op Tune OS: Cockpit (https://<IP>:9443), logboeken van de dienst tune.",
