  "settings.clearLibraryV2Hint": "Wist de index (nummers, albums, artiesten). Daarmee gaan ook verloren: de inhoud van afspeellijsten, waarderingen, bladwijzers, favorieten, met de hand samengestelde boxsets en albumbewerkingen. Er wordt geen muziekbestand verwijderd. Vlak daarvoor wordt een back-up van de database gemaakt. Een scan brengt alleen de nummers terug. Wil je de bibliotheek vernieuwen, start dan liever een volledige scan: die behoudt boxsets en albumbewerkingen.",
  "settings.clearLibraryBusyHint": "Er loopt een scan: wacht tot die klaar is voordat je de bibliotheek leegmaakt.",
  "settings.scanOptions": "Scanopties",
  "settings.qualitySplit": "Albums splitsen op kwaliteit",
  "settings.qualitySplitHint": "Als hetzelfde album in cd- en hi-res-kwaliteit bestaat, twee aparte items maken (bijv. \"Album (96kHz/24bit)\")",
  "settings.autoBoxSets": "Automatische boxsets",
  "settings.autoBoxSetsHint": "Voegt schijven in naast elkaar gelegen mappen (CD1, CD2…) samen tot één album en zet albums met meerdere mappen onder Boxsets. Uit: er wordt niets samengevoegd, en een album met meerdere schijven staat niet meer onder Boxsets. Al samengevoegde boxsets blijven samengevoegd: met “Boxset ongedaan maken” op hun pagina splits je ze weer in hun schijven.",
  "settings.scanImportPlaylists": "Bij het scannen gevonden .m3u/.pls-afspeellijsten importeren",
  "settings.scanImportPlaylistsHint": "De scan zet de .m3u-, .m3u8- en .pls-bestanden in je muziekmappen om in afspeellijsten. Uit: hij maakt er geen meer aan. Al geïmporteerde afspeellijsten blijven staan; de knop hieronder verwijdert ze.",
  "settings.removeScanPlaylists": "Door de scan geïmporteerde afspeellijsten verwijderen",
  "settings.removeScanPlaylistsHint": "Verwijdert de afspeellijsten die de scan uit .m3u/.pls-bestanden heeft gemaakt. Afspeellijsten die in Tune zijn gemaakt, blijven onaangeroerd.",
  "settings.removeScanPlaylistsConfirm": "Door de scan geïmporteerde afspeellijsten verwijderen ({n})? Afspeellijsten die in Tune zijn gemaakt, blijven onaangeroerd.",
