  "renderer.wav24": "24 bit",
  "renderer.wav24Hint": "Echte 24-bit WAV leveren. Standaard aangeboden; alleen geweigerd als de detectietest aantoont dat deze renderer audio/L24 noch audio/wav aangeeft.",
  "renderer.depthCapNotRate": "Let op: de bitdiepte beperken beperkt niet de samplefrequentie. Een bestand van 96 kHz/24 bit wordt 96 kHz/16 bit — nog steeds 96 kHz. Gaat je renderer maar tot 48 kHz, stel dan ook “Max. samplefrequentie” in.",
  "renderer.flacAndWavSplitBySource": "“WAV afdwingen” geldt alleen voor bronnen die geen FLAC zijn (ALAC, AAC…) — het omzeilt de ALAC-decoder van de renderer. Je FLAC-bestanden worden nog steeds als native FLAC geleverd.",
  "renderer.wav24Unproven": "Er is nog geen detectietest geslaagd: 24 bit blijft beschikbaar, maar niets bevestigt dat dit apparaat het kan afspelen. Druk hierboven op “Controleren”.",
  "renderer.wav24Refused": "De detectietest gaf als antwoord: dit apparaat geeft audio/L24 noch audio/wav aan. 24 bit blijft uitgeschakeld — dat leveren zou stilte opleveren.",
  "renderer.startDelay": "Startvertraging",
  "renderer.startDelayHint": "Pauze voordat het afspelen begint, zodat een DLNA-versterker kan bufferen (helpt als de eerste seconden haperen). 0 = standaard.",
  "renderer.fluxContinu": "Doorlopende stream tussen nummers",
  "renderer.fluxContinuHint": "Voor spelers die twee opeenvolgende nummers slecht aan elkaar koppelen: opeenvolgende nummers in hetzelfde formaat worden als één WAV-stream verstuurd, zonder bewerking. Bij de eerste formaatwissel wordt weer normaal van nummer naar nummer afgespeeld.",
  "renderer.probeFailed": "Kon de mogelijkheden van de renderer niet lezen. De server kon de precieze oorzaak niet vaststellen.",
