  "renderer.probeSoapFailed": "De renderer is gevonden, maar het opvragen van de mogelijkheden is mislukt. Probeer het opnieuw; als hij al afspeelt, hoef je niets aan het netwerk te veranderen.",
  "renderer.saveError": "Kon de instelling niet opslaan.",
  "renderer.saveConfig": "Deze configuratie opslaan",
  "renderer.saveConfigHint": "Deze instellingen worden al toegepast op het apparaat zodra je klikt. Deze knop bewaart daarnaast een blijvende kopie die aan dit apparaat is gekoppeld: je kunt die vanuit dit scherm altijd terugzetten.",
  "renderer.saveConfigNoKey": "Deze zone heeft geen uitvoer-ID en geen naam: er is niets waaraan een opgeslagen configuratie kan worden gekoppeld.",
  "renderer.configSavedOn": "Configuratie opgeslagen op {date}",
  "renderer.configByName": "Zonder uitvoer-ID is deze configuratie gekoppeld aan de NAAM van de zone: als je die wijzigt, raakt de koppeling verloren.",
