  "renderer.restoringConfig": "Bezig met terugzetten…",
  "renderer.forgetConfig": "Vergeten",
  "renderer.resetCompat": "Compatibiliteit resetten",
  "renderer.resetCompatHint": "Nadat deze renderer een commando heeft geweigerd, onthoudt Tune de vorm van het commando die hij wel accepteerde en gebruikt die opnieuw, ook na een herstart. Na een reset begint het volgende nummer weer met het volledige commando.",
  "renderer.resetCompatDone": "Compatibiliteit gereset: vergeten profielen: {n}.",
  "renderer.resetCompatNone": "Geen aangeleerd profiel voor deze renderer: niets te resetten.",
  "renderer.resetCompatError": "Resetten van de compatibiliteit mislukt.",
  "settings.dlnaCap16bitHint": "Inschakelen als hi-res (24 bit) stil blijft op deze renderer terwijl 16 bit werkt (Ruark R3). Codeert opnieuw naar 16-bit FLAC in plaats van direct 24 bit te sturen die de renderer niet kan decoderen.",
  "settings.alacPassthroughHint": "ALAC ongewijzigd naar deze renderer sturen (bit-perfect, geen transcodering naar FLAC). Schakel dit alleen in als de renderer ALAC native decodeert, anders is er geen geluid.",
  "settings.aacPassthroughHint": "AAC ongewijzigd naar deze renderer sturen in plaats van het naar FLAC te transcoderen. De bron is al met verlies gecomprimeerd, dus transcoderen voegt geen kwaliteit toe — het vertraagt alleen het eerste geluid. Schakel dit alleen in als de renderer AAC native decodeert, anders is er geen geluid.",
  "settings.hqplayerHint": "Verbind Tune met HQPlayer voor upsampling en audiofiele filters. Standaardpoort: 4321 (v4/v5) of 8019 (v6).",
