  "settings.unlinkAccountRefusedAdmin": "Meld u aan als beheerder om het account te ontkoppelen.",
  "settings.cloudDisconnected": "Uitgelogd bij de cloud",
  "settings.signOutConfirm": "Deze server ontkoppelen van het mozaiklabs.fr-account? Deze server wordt dan losgekoppeld van het account: de online kopie van de bibliotheek en de Tune Circle-shares worden verwijderd, en premiumfuncties die via het account komen, stoppen (een licentiesleutel blijft actief). Je kunt daarna weer inloggen.",
  "settings.licenseRateLimited": "Te veel pogingen — wacht een minuut voordat je het opnieuw probeert.",
  "settings.cloudComingSoon": "Cloud binnenkort beschikbaar op deze server",
  "settings.telemetry": "Telemetrie",
  "settings.telemetryHint": "Gebruiksstatistieken versturen om Tune te verbeteren: installatie-ID, versie, platform, omvang van de bibliotheek, verbonden diensten en apparaatmodellen.",
  "settings.telemetryOffScope": "Uitschakelen stopt ook het delen en downloaden van communitymetadata. De licentievalidatie loopt gewoon door, dus je raakt Premium nooit kwijt.",
  "settings.communitySync": "Metadata delen met de community",
  "settings.communitySyncHint": "Doe mee aan de verrijking door de community: MusicBrainz-koppelingen, genres en credits (componist, dirigent, uitvoerenden) gedeeld tussen Tune-servers. Anoniem — nooit je bestanden.",
  "settings.cloudListens": "Mijn luistergeschiedenis naar mijn account sturen",
  "settings.cloudListensHint": "Voegt wat je op deze server beluistert toe aan de pagina “Mijn luistergeschiedenis” van je account, samen met je andere Tune-servers. Per keer luisteren: de datum, de duur, een anonieme profiel-ID, de titel, artiest, album en, als die bekend zijn, de ISRC en MusicBrainz-ID. Nooit je bestandspaden, je IP-adres of de namen van je zones. Standaard uit.",
  "settings.cloudListensLink": "Mijn luistergeschiedenis bekijken op mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Je luistergeschiedenis delen met je mozaiklabs.fr-account?",
  "settings.cloudListensConsentIntro": "Tune kan wat je op deze server beluistert toevoegen aan je mozaiklabs.fr-account. Er wordt niets verstuurd zolang je niet hebt geantwoord.",
  "settings.cloudListensConsentSentLabel": "Wat er wordt verstuurd:",
  "settings.cloudListensConsentSent": "per keer luisteren de datum, de duur, de titel, artiest, album, een anonieme profiel-ID en, als die bekend zijn, de ISRC- en MusicBrainz-ID's.",
  "settings.cloudListensConsentNeverLabel": "Wat er nooit wordt verstuurd:",
  "settings.cloudListensConsentNever": "je bestandspaden, je IP-adres, de namen van je zones en de namen van je profielen.",
  "settings.cloudListensConsentBenefit": "Wat het je oplevert: de pagina “Mijn luistergeschiedenis”, die de luistergeschiedenis van al je Tune-servers bundelt, en wat de community beluistert.",
  "settings.cloudListensConsentSettingsReminder": "Je kunt op elk moment van gedachten veranderen via Instellingen › Systeem.",
  "settings.cloudListensConsentError": "Je antwoord kon niet worden opgeslagen. Probeer het opnieuw.",
  "settings.cloudListensConsentNo": "Nee",
  "settings.cloudListensConsentYes": "Ja, delen",
  "settings.cloudListensConsentClose": "Sluiten zonder te antwoorden",
  "settings.communityShare": "Mijn waarderingen en luistergeschiedenis (anoniem) delen met de community",
  "settings.communityShareHint": "Staat los van “Mijn luistergeschiedenis” en is standaard uit. Je albumwaarderingen (zonder commentaar) en wat je account NA het inschakelen ontvangt aan luistergeschiedenis, tellen mee in openbare, anonieme totalen, die op een albumpagina worden getoond vanaf drie verschillende personen. Er worden nooit individuele gegevens getoond. Uitschakelen verwijdert je bijdrage meteen.",
  "settings.communityMeasuresReceive": "Analyseresultaten van de community ontvangen",
  "settings.communityMeasuresReceiveHint": "Standaard uit. Voor je FLAC-bestanden vraagt de server mozaiklabs.fr om ReplayGain, dynamisch bereik en akoestische vingerafdrukken die al op precies hetzelfde signaal zijn gemeten door minstens twee andere installaties. Ze vullen alleen aan wat ontbreekt: je tags en je eigen metingen worden nooit vervangen. De site ontvangt alleen een kort voorvoegsel, nooit de lijst van je bestanden.",
  "settings.communityMeasuresContribute": "Mijn analyseresultaten delen met de community",
  "settings.communityMeasuresContributeHint": "Standaard uit. De server stuurt de site alleen de metingen die hij zelf op je FLAC-bestanden heeft gedaan (ReplayGain, dynamisch bereik, akoestische vingerafdruk), herkenbaar aan de handtekening van hun signaal. Er wordt geen pad, titel, bestandsnaam of account verstuurd: de server identificeert zich met zijn installatienummer. Uitschakelen wist wat is verstuurd.",
