  "v2.set.barVu": "Afspeelbalk met VU-meters",
  "v2.set.barVuHint": "Alleen weergave — het signaal verandert niet. Twee naaldmeters aan weerszijden van de bediening; ze vervangen de piekindicatoren en het mini-spectrum. Op een smalle balk komt de gewone balk terug.",
  "v2.set.barOnde": "Voortgangsbalk als golfvorm",
  "v2.set.barOndeHint": "Alleen weergave. De voortgangsbalk in Speelt nu en in de afspeelbalk tekent de golfvorm van het nummer: het afgespeelde deel in kleur, de rest gedimd. Voor nummers uit de bibliotheek, en voor Qobuz en TIDAL met de optie hieronder; radio en andere streams houden de gewone balk.",
  "v2.set.ondeStreaming": "Golfvorm voor streamingnummers",
  "v2.set.ondeStreamingHint": "Qobuz en TIDAL: na 30 s luisteren downloadt de server het nummer één keer om de golfvorm te berekenen, en bewaart hem daarna. Als dit uit staat, houden deze nummers de gewone balk en wordt er niets gedownload. Vereist de voortgangsbalk als golfvorm.",
  "v2.set.barViz": "Visualisatie in de afspeelbalk",
