  "v2.hint.volumeDisplay": "Hoe het volume wordt weergegeven. Decibel geeft de werkelijke versterking aan; het percentage is een weergaveschaal, geen meting.",
  "v2.hint.ingestMode": "🔴 “Verplaatsen” haalt het bestand weg van de oorspronkelijke plek. “Kopiëren” laat het staan en neemt twee keer zoveel ruimte in.",
  "v2.hint.audioBackend": "Het stuurprogramma waarlangs het geluid naar buiten gaat. ASIO vereist een stuurprogramma van de fabrikant; zonder dat blijft de uitvoer stil.",
  "v2.hint.wasapiMode": "In exclusieve modus neemt Tune de geluidskaart helemaal voor zichzelf: de stream gaat bit-perfect naar buiten, maar andere apps worden stil.",
