  "upsampling.eyebrow": "Premium-plug-in",
  "upsampling.title": "Upsampling",
  "upsampling.lead": "Verhoogt de samplefrequentie van de bron naar de hoogste frequentie die de DAC accepteert, binnen dezelfde familie (44,1 → 352,8 kHz, 48 → 384 kHz), op de lokale uitvoer. Het niveau wordt 3 dB verlaagd en een veiligheidslimiter houdt de zeldzame resterende pieken tegen: geen clipping. Het volume van Tune geeft deze 3 dB terug: het niveau is gelijk aan afspelen zonder upsampling zolang het volume op −3 dB of lager staat (op 100% regel je het niveau op de DAC of de voorversterker).",
  "upsampling.noZone": "Kies een zone om de upsampling ervan in te stellen.",
  "upsampling.bitPerfect": "Als upsampling actief is, verandert elke sample: het pad is niet langer bit-perfect. De PURE-modus omzeilt het altijd, en een DoP-stream wordt nooit geüpsampled.",
  "upsampling.enabled": "Upsampling voor deze zone",
  "upsampling.enabledHint": "Standaard uit. Alleen lokale uitvoer, op een DAC waarvan de samplefrequenties zijn gemeten. Op macOS en Windows alleen in gedeelde modus (niet in exclusieve modus, niet met ASIO); op Linux ook met directe hw:-uitvoer. Native DSD en volledig gedecodeerde gecomprimeerde streams worden niet geüpsampled.",
  "upsampling.filter": "Filter",
  "upsampling.filterHint": "Alleen de filters die deze machine in realtime aankan (met een marge van ×3) worden aangeboden. Tussen haakjes: de niveauverlaging.",
  "upsampling.filterNotAdmitted": "Deze machine kan dit filter niet in realtime uitvoeren: het wordt niet toegepast. Kies een ander filter of meet de machine opnieuw.",
  "upsampling.target": "Doelfrequentie",
  "upsampling.targetHint": "Een geheel veelvoud van de bron, nooit hoger dan wat de DAC accepteert.",
  "upsampling.targetMax": "Maximum van de DAC",
  "upsampling.dither": "Dither",
  "upsampling.ditherHint": "Die van de uitvoer zelf, bij het verkleinen van de bitdiepte: TPDF, zonder noise shaping.",
  "upsampling.machine": "Machinetest",
  "upsampling.machineResult": "{admitted} van {total} filters draaien in realtime op deze machine.",
  "upsampling.machineNone": "Nog niet gemeten: de meting gebeurt bij de eerste keer opslaan (een paar seconden).",
  "upsampling.remeasure": "De machine opnieuw meten",
  "upsampling.nextTrack": "Opgeslagen: de instelling geldt vanaf de volgende stream.",
  "upsampling.appliesLater": "De instelling geldt vanaf de volgende stream.",
  "upsampling.saved": "Opgeslagen.",
  "upsampling.appliesNow": "De instelling wordt direct toegepast: het afspelen gaat na ongeveer een seconde stilte verder op dezelfde positie.",
  "upsampling.applied": "Toegepast.",
  "upsampling.appliedRestart": "Toegepast: het afspelen gaat verder op dezelfde positie.",
  "upsampling.save": "Opslaan",
  "upsampling.constraint.premium": "Upsampling maakt deel uit van Tune Premium: je instellingen blijven bewaard en worden toegepast met Premium.",
  "upsampling.constraint.notInstalled": "Installeer de plug-in “Upsampling” via Extensies om het toe te passen.",
