  "nowplaying.eqPureNotice": "De PURE-modus staat aan voor deze zone: het signaal wordt onbewerkt doorgegeven, zonder enige verwerking. De voorinstellingen hieronder hebben geen effect zolang de PURE-modus aan staat.",
  "settings.fixedSampleRate": "Vaste samplefrequentie voor de uitvoer",
  "settings.fixedSampleRateOff": "Uit",
  "settings.fixedSampleRateHint": "Geldt vanaf het volgende nummer, ook voor bronnen uit een andere frequentiefamilie. Inactief in de PURE-modus of bij strikt bit-perfect. Boven de limiet van de uitvoer past Tune die limiet toe en toont dat in het signaalpad.",
  "settings.zoneExclusiveMode": "Exclusieve modus van de zone",
  "settings.zoneExclusiveFollow": "Zoals de instelling van de machine",
  "settings.zoneExclusiveOn": "Exclusief",
  "settings.zoneExclusiveOff": "Gedeeld",
  "settings.zoneExclusiveHint": "Alleen voor het lokale apparaat van deze zone. In exclusieve modus is Tune de enige app die het apparaat gebruikt; in gedeelde modus houden andere apps hun geluid. Wordt direct toegepast als er niets speelt, anders aan het einde van het huidige afspelen.",
  "settings.zoneExclusivePending": "Nog niet toegepast: de uitvoer houdt zijn modus tot het huidige afspelen is afgelopen, of het stuurprogramma legt zijn eigen modus op (ASIO).",
  "settings.wasapiPeriod": "Periode voor exclusieve WASAPI",
  "settings.wasapiPeriodAuto": "Automatisch (periode van het stuurprogramma)",
  "settings.wasapiPeriodHint": "Duur van elke buffer die in exclusieve modus naar het apparaat wordt gestuurd (Windows). Automatisch past bij de meeste DAC's. Als het geluid met een USB-DAC af en toe hapert (“als een plaat die overslaat”), probeer dan 50 ms. Geldt vanaf het volgende gestarte nummer; als het stuurprogramma de waarde weigert, valt Tune terug op de periode van het stuurprogramma.",
  "zone.pauseThisZone": "{name} pauzeren",
  "pareFeu.titre": "Windows Firewall filtert Tune op dit netwerk",
  "pareFeu.corps": "Het actieve netwerk is ingedeeld als {profils}, en de firewallregel van Tune geldt daar niet voor. Het detecteren van UPnP/DLNA-apparaten en de toegang vanaf een telefoon zijn daardoor geblokkeerd: een apparaat verschijnt misschien alleen als AirPlay, of ontvangt niets.",
  "pareFeu.etapePrive": "Zet het netwerk op Privé: Windows-instellingen ▸ Netwerk en internet ▸ netwerkeigenschappen ▸ Netwerkprofiel: Privé.",
  "pareFeu.etapeAutoriser": "Of sta Tune toe op dit netwerk: Windows-beveiliging ▸ Firewall- en netwerkbeveiliging ▸ Een app toestaan via de firewall ▸ tune-server.exe.",
  "pareFeu.etapeRedemarrer": "Start Tune daarna opnieuw.",
  "pareFeu.profilDomaine": "Domein",
  "pareFeu.profilPrive": "Privé",
  "pareFeu.profilPublic": "Openbaar",
  "pareFeu.corpsBlocage": "Een firewallregel blokkeert tune-server.exe op dit netwerk ({profils}): {regles}. Die regel gaat vóór de toestemming die is aangevinkt bij “Een app toestaan via de firewall”, waar hij niet verschijnt. Het detecteren van UPnP/DLNA-apparaten en de toegang vanaf een telefoon blijven daardoor geblokkeerd.",
  "pareFeu.etapeSupprimerBlocage": "Verwijder alle blokkeringsregels met de naam {regles} (vaak twee: TCP en UDP): Windows Defender Firewall ▸ Geavanceerde instellingen ▸ Regels voor binnenkomende verbindingen ▸ regels met het blokkeringspictogram ▸ Verwijderen.",
  "pareFeu.corpsAutreChemin": "Tune is toegestaan in de firewall, maar voor een andere locatie dan het programma dat draait. Op dit netwerk ({profils}) zijn het detecteren van UPnP/DLNA-apparaten en de toegang vanaf een telefoon daardoor geblokkeerd.",
  "pareFeu.programmeLance": "Actief programma: {chemin}",
  "pareFeu.cheminsAutorises": "Toegestaan: {chemins}",
  "pareFeu.etapeAutoriserLance": "Sta het actieve programma toe: Windows-beveiliging ▸ Firewall- en netwerkbeveiliging ▸ Een app toestaan via de firewall ▸ Andere app toestaan… ▸ {chemin}.",
  "pareFeu.etapeAutoriserSeule": "Sta Tune toe op dit netwerk: Windows-beveiliging ▸ Firewall- en netwerkbeveiliging ▸ Een app toestaan via de firewall ▸ tune-server.exe.",
