  "settings.fauxHiRes": "Aangetaste bronnen detecteren",
  "settings.fauxHiResHint": "Tune controleert of je verliesvrije bestanden (FLAC, WAV, AIFF, ALAC…) echt bevatten wat ze beweren: werkelijk gebruikte bits en afsnijding van het spectrum, om een geüpsamplede cd of een bestand op basis van een MP3 op te sporen. De analyse draait op de achtergrond en maakt plaats tijdens het afspelen; ze luistert naar 12 fragmenten van vijf seconden per nummer, wat bij een grote bibliotheek enkele uren kan duren.",
